   "source": [
    "data = read.csv(\"https://raw.githubusercontent.com/blacktreeM/econ/refs/heads/main/cbb.csv\")\n",
    "library(ggplot2); library(tidyverse)\n",
    "data = subset(data, select = c(TEAM, YEAR, POSTSEASON, G, W, EFG_O, TOR, ORB, FTR, EFG_D, TORD, DRB, FTRD))\n",
    "nrow(data); summary(data); table(data$YEAR)\n",
    "options(repr.plot.width = 15, repr.plot.height = 12); options(warn = -1)\n",
    "r64 = c('R64', 'R32', 'S16', 'E8', 'F4', '2ND', 'Champions')\n",
    "e8 = c('E8', 'F4', '2ND', 'Champions')\n",
    "s16 = c('S16', 'E8', 'F4', '2ND', 'Champions')\n",
    "data$R64 = ifelse(data$POSTSEASON %in% r64, 1, 0)\n",
    "data$E8 = ifelse(data$POSTSEASON %in% e8, 1, 0)\n",
    "data$S16 = ifelse(data$POSTSEASON %in% s16, 1, 0)\n",
    "table(data$R64, data$YEAR)\n",
    "table(data$E8, data$YEAR)\n",
    "table(data$S16, data$YEAR)"
   ]
  },
