   "source": [
    "plot_data <- data %>%\n",
    "  pivot_longer(\n",
    "    cols = c(EFG_O, TOR, ORB, FTR), \n",
    "    names_to = \"Variable\", \n",
    "    values_to = \"Value\"\n",
    "  ) %>%\n",
    "  mutate(Variable = case_match(Variable,\n",
    "    \"EFG_O\" ~ \"Effective FG %\",\n",
    "    \"TOR\"   ~ \"Turnover %\",\n",
    "    \"ORB\"   ~ \"Offensive Rebound %\",\n",
    "    \"FTR\"   ~ \"Free Throw Rate\"\n",
    "  ))\n",
    "options(repr.plot.width = 15, repr.plot.height = 40)\n",
    "ggplot(plot_data, aes(x = Value, y = W)) +\n",
    "  geom_point(alpha = 0.4, size = 1, color = \"blue\") + \n",
    "  geom_smooth(method = \"lm\", color = \"red\", se = FALSE) + \n",
    "  facet_wrap(Variable ~ YEAR, scales = \"free_x\", nrow = 8) + \n",
    "  labs(\n",
    "    title = \"The Four Factors vs. Number of Wins by Year (2022-2025)\",\n",
    "    x = \"Factor Value\",\n",
    "    y = \"Total Wins\"\n",
    "  ) +\n",
    "  theme_minimal() +\n",
    "  theme(\n",
    "    strip.background = element_rect(fill = \"gray95\"),\n",
    "    strip.text = element_text(face = \"bold\", size = 9), \n",
    "    panel.spacing = unit(1, \"lines\")\n",
    "  )"
   ]
  },
