   "source": [
    "model = lm(W ~ EFG_O + TOR + ORB + FTR, data)\n",
    "summary(model)\n",
    "coeffs = abs(coef(model)[-1])\n",
    "coeffs / sum(coeffs) * 100\n",
    "#factors = c(\"Shooting (eFG%)\", \"Turnovers (TOV%)\", \"Rebounding (ORB%)\", \"Free Throws (FT Rate)\")\n",
