    "    model = lm(W ~ EFG_O + TOR + ORB + FTR, data = .x) \n",
    "    coeffs = abs(coef(model)[2:5])\n",
    "    importance = (coeffs / sum(coeffs)) * 100\n",
    "    data.frame(\n",
    "      Factor = c(\"Shooting\", \"Turnovers\", \"Rebounding\", \"Free Throws\"),\n",
    "      Importance = round(importance, 2)\n",
    "    )\n",
    "  }) %>% ungroup()\n",
    "tail(yearly_importance)\n",
    "options(repr.plot.width = 15, repr.plot.height = 6)\n",
    "ggplot(yearly_importance, aes(x = YEAR, y = Importance, color = Factor, group = Factor)) +\n",
    "  geom_line(linewidth = 1.2) + scale_x_continuous(breaks = c(2013:2019, 2021:2025)) +\n",
    "  geom_point() +\n",
    "  labs(title = \"Evolution of the Four Factors Importance\",\n",
    "       y = \"Importance (%)\",\n",
    "       x = \"\") +\n",
    "  theme_minimal() + theme(legend.position = 'bottom', legend.text = element_text(size = 18),\n",
    "                         legend.title = element_blank())"
   ]
  },
