   "source": [
    "plot_data <- data %>% filter(R64 == 1)\n",
    "ggplot(plot_data, aes(x = EFG_O, y = W)) +\n",
    "  geom_text(\n",
    "    aes(label = TEAM, color = POSTSEASON == \"Champions\", \n",
    "        fontface = ifelse(POSTSEASON == \"Champions\", \"bold\", \"plain\")), \n",
    "    size = 2.5, \n",
    "    check_overlap = TRUE\n",
    "  ) + \n",
    "  geom_smooth(method = \"lm\", color = \"black\", linetype = \"dashed\", se = FALSE) + \n",
    "  facet_wrap(~ YEAR, ncol = 4) + \n",
    "  scale_color_manual(values = c(\"FALSE\" = \"blue\", \"TRUE\" = \"red\"), guide = \"none\") +\n",
    "  labs(\n",
    "    title = \"Effective FG % vs. Number of Wins (2022-2025)\",\n",
    "    subtitle = \"Champions highlighted in red\",\n",
    "    x = \"Effective Field Goal % (EFG_O)\",\n",
    "    y = \"Total Wins\"\n",
    "  ) +\n",
    "  theme_minimal() +\n",
    "  theme(\n",
    "    strip.background = element_rect(fill = \"gray95\"),\n",
    "    strip.text = element_text(face = \"bold\", size = 10),\n",
    "    panel.spacing = unit(1.5, \"lines\")\n",
    "  )"
   ]
  },
