   "source": [
    "yearly_importance <- data %>% group_by(YEAR) %>%\n",
    "  group_modify(~ {\n",
    "    model = lm(R64 ~ EFG_O + TOR + ORB + FTR + EFG_D + TORD + DRB + FTRD, data = .x)\n",
    "    coeffs = abs(coef(model)[2:5])\n",
    "    importance = (coeffs / sum(coeffs)) * 100\n",
    "    data.frame(\n",
    "      Factor = c(\"Shooting (eFG%)\", \"Turnovers (TOV%)\", \"Rebounding (ORB%)\", \"Free Throws (FT Rate)\"),\n",
    "      Importance = round(importance, 2)\n",
    "    )\n",
    "  }) %>% ungroup()\n",
    "options(repr.plot.width = 15, repr.plot.height = 8)\n",
    "ggplot(yearly_importance, aes(x = YEAR, y = Importance, color = Factor, group = Factor)) +\n",
    "  geom_line(linewidth = 1.2) +\n",
    "  geom_point() +\n",
    "  labs(title = \"Evolution of the Four Factors Importance\",\n",
    "       y = \"Importance (%)\",\n",
    "       x = \"\") +\n",
    "  theme_minimal() + theme(legend.position = 'bottom', legend.text = element_text(size = 18),\n",
    "                         legend.title = element_blank())\n",
    "# The \"Three-Point Revolution\": Students will likely see the importance of Shooting (eFG%) \n",
    "#trend upwards over the last decade. This is a perfect way to discuss structural breaks in data—where the \"math\" of the game changed because of the increased volume of 3-point shots."
   ]
  }
 ],
